// TH18 v1.00a st06bs.ecl::BossCard3 (source 911-978) + BossCard3_at (979-1021) + BossCard3_at2 (1023-1083).
// Source t0 = 920 timerReset. First two async waves launch at source t=120; source timeout 3300 -> Boss4.
// Shell: 120-frame opening buffer, then the source timeline (120 + 3300 = 3420 frames).
const TIME_LIMIT: int = 3420;
const SOURCE_LIMIT: int = 3300;
const TH18_BALL2: int = 432; // source etSprite type5; TH18 bullet table row 432
const G_BOSS_X: int = 16;    // free globals: live real-boss position for VELTIME s=5000000 (toward boss0)
const G_BOSS_Y: int = 17;

// ---- BossCard3_at (source 979-1021), emitter 0 ------------------------------------------------
xformdef AT_MOTION {
    // source 997-1000: ANIM(a=1) birth stage omitted (accepted); OFFSCREEN(a=300);
    // WAIT(60); VELTIME(a=240, r=2.0, s=5000000 => direction to boss0 at effect entry).
    offscreen_keep(300);
    wait(60);
    // VELTIME: v += ((2.0 - speed_at_entry)/240) * unit(dir to boss0); scalar/vector split preserved.
    set_gravity(
        at_effect((2fx - $self_speed) / 240fx
            * cos(atan2((global(G_BOSS_Y) as fx) - $self_y,
                        (global(G_BOSS_X) as fx) - $self_x))),
        at_effect((2fx - $self_speed) / 240fx
            * sin(atan2((global(G_BOSS_Y) as fx) - $self_y,
                        (global(G_BOSS_X) as fx) - $self_x))));
    wait(240);
    set_gravity(0fx, 0fx);
}

// ---- BossCard3_at2 (source 1023-1083), emitter 1 ----------------------------------------------
// HOMING is v += (1.5*unit(aim_player) - v) * 0.008 each tick.  Re-arming a 125-frame linear
// STEP every tick at the same slot applies exactly (target-current)/125 per tick (=0.008).
// The last re-arm is left to converge over its 125 frames, so homing totals a=200/500/1000.
// Then VELTIME(a=60, r=2.0, s=-9999994 => current bullet angle): step_speed along that angle.
xformdef AT2_MOTION_E {
    offscreen_keep(300); // source 1043-1051: OFFSCREEN(300)
    wait(60);            // source 1052: WAIT(60)
homing:
    step_vx(at_effect(1.5fx * cos(aim_player())), 125 + 65536 * EASE_LINEAR);
    step_vy(at_effect(1.5fx * sin(aim_player())), 125 + 65536 * EASE_LINEAR);
    wait(1);
    loop(homing, 75);    // 75 ticks + final 125-frame ease = 200
    wait(125);
    step_speed(2fx, 60 + 65536 * EASE_LINEAR); // source 1063: VELTIME a=60 from current speed
}
xformdef AT2_MOTION_N {
    offscreen_keep(300);
    wait(60);
homing:
    step_vx(at_effect(1.5fx * cos(aim_player())), 125 + 65536 * EASE_LINEAR);
    step_vy(at_effect(1.5fx * sin(aim_player())), 125 + 65536 * EASE_LINEAR);
    wait(1);
    loop(homing, 375);   // 375 + 125 = 500
    wait(125);
    step_speed(2fx, 60 + 65536 * EASE_LINEAR);
}
xformdef AT2_MOTION_HL {
    offscreen_keep(1000); // source 1046-1049: OFFSCREEN(1000)
    wait(60);
homing:
    step_vx(at_effect(1.5fx * cos(aim_player())), 125 + 65536 * EASE_LINEAR);
    step_vy(at_effect(1.5fx * sin(aim_player())), 125 + 65536 * EASE_LINEAR);
    wait(1);
    loop(homing, 875);   // 875 + 125 = 1000
    wait(125);
    step_speed(2fx, 60 + 65536 * EASE_LINEAR);
}

// Live boss position for the at-wave VELTIME "toward boss0" direction (source 1000).
async sub boss_track() {
    loop {
        set_global(G_BOSS_X, $self_x as int);
        set_global(G_BOSS_Y, $self_y as int);
        wait(1);
    }
}

// source 995-1017: fixed-direction ring (etAim 3), base angle = RANDRAD per wave,
// emitter origin = player position, etDist(-128) along each bullet's own angle.
async sub ring_at() {
    var count: int = 11;
    var interval: int = 180;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { count = 16; }
    if rank == 2 { count = 24; interval = 170; }
    if rank == 3 { count = 26; interval = 160; }
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4); // source 984: etSprite(0,5,4)
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_speed(0, 0.2fx, 0fx); // source 996: etSpeed(0.2,1.0), single layer
    sh_xform(0, AT_MOTION);
    loop {
        if $frame >= self_int(0) { return; }
        sh_angle(0, (rand(65536) - 32768) as angle, 0deg); // RANDRAD [-pi,pi)
        sh_offset_abs(0, $player_x, $player_y);
        sh_dist(0, -128.8fx); // etDist(-128) plus ANIM a=1 retreat 4*0.2
        sh_fire(0);
        wait(interval);
    }
}

// source 1038-1079: fixed-direction ring around the boss (no etOffsetAbs), random base angle,
// etDist(-128); OFFSCREEN + HOMING/VELTIME xform.
async sub ring_at2() {
    var count: int = 11;
    var interval: int = 180;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { count = 16; }
    if rank == 2 { count = 24; interval = 170; }
    if rank == 3 { count = 32; interval = 160; }
    sh_reset(1);
    sh_sprite(1, TH18_BALL2, 2); // source 1028: etSprite(0,5,2)
    sh_aim(1, 0);
    sh_ring(1, 1);
    sh_count(1, count, 1);
    sh_speed(1, 0.2fx, 0fx);
    if rank == 0 { sh_xform(1, AT2_MOTION_E); }
    else if rank == 1 { sh_xform(1, AT2_MOTION_N); }
    else { sh_xform(1, AT2_MOTION_HL); }
    loop {
        if $frame >= self_int(0) { return; }
        sh_angle(1, (rand(65536) - 32768) as angle, 0deg);
        sh_dist(1, -128.8fx); // etDist(-128) plus ANIM a=1 retreat 4*0.2
        sh_fire(1);
        wait(interval);
    }
}

// Real boss: upstream Boss() put it at (0,128) with hurtbox40/hitbox48; this sub keeps its
// source judgement (circle halves 20/24), invulnerable for the whole training segment.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx); // source Boss() 33: setHurtbox(40,40)
    set_hitbox(24fx);  // source Boss() 34: setHitbox(48,48)
    wait(120);         // opening buffer; attack timeline starts here
    set_self_int(0, $frame + SOURCE_LIMIT);
    spawn boss_track();
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // source 947: movePosTime(60,4,0,128)
    wait(60);  // source +60 label
    wait(60);  // source +120 label
    spawn ring_at();  // source 959
    spawn ring_at2(); // source 960
    loop {
        if global(GVAR_RANK) >= 3 {
            // source 963-966: only DIFF>=3 sweeps; mode9 = quadratic in-out, 240 frames each way.
            move_to(240, 96fx, 128fx, EASE_QUAD_IN_OUT);
            wait(240);
            move_to(240, -96fx, 128fx, EASE_QUAD_IN_OUT);
            wait(240);
        } else {
            wait(240); // source 968: BossCard3_1388 wait(240)
        }
        if $frame >= self_int(0) { return; }
    }
}

// Control enemy at (0,0): segment owner, never body-collides; real boss above keeps source judgement.
async sub control_pattern() {
    loop { wait(60); }
}
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 68, control_pattern, TIME_LIMIT, 0, 0, 0); // source 941/943/945 spell(68,3300)
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
